$lightThemeSystem = 0;
$lightThemeApps = 0;
$accentColorOnStart = 0;
$enableTransparency = 1;
$htmlAccentColor = '#0078D4';
& {
	$params = @{
		LiteralPath = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize';
		Force = $true;
		Type = 'DWord';
	};
	Set-ItemProperty @params -Name 'SystemUsesLightTheme' -Value $lightThemeSystem;
	Set-ItemProperty @params -Name 'AppsUseLightTheme' -Value $lightThemeApps;
	Set-ItemProperty @params -Name 'ColorPrevalence' -Value $accentColorOnStart;
	Set-ItemProperty @params -Name 'EnableTransparency' -Value $enableTransparency;
};
& {
	Add-Type -AssemblyName 'System.Drawing';
	$accentColor = [System.Drawing.ColorTranslator]::FromHtml( $htmlAccentColor );

	function ConvertTo-DWord {
		param(
			[System.Drawing.Color]
			$Color
		);

		[byte[]] $bytes = @(
			$Color.R;
			$Color.G;
			$Color.B;
			$Color.A;
		);
		return [System.BitConverter]::ToUInt32( $bytes, 0); 
	}

	$startColor = [System.Drawing.Color]::FromArgb( 0xD2, $accentColor );
	Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent' -Name 'StartColorMenu' -Value( ConvertTo-DWord -Color $accentColor ) -Type 'DWord' -Force;
	Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent' -Name 'AccentColorMenu' -Value( ConvertTo-DWord -Color $accentColor ) -Type 'DWord' -Force;
	Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\DWM' -Name 'AccentColor' -Value( ConvertTo-DWord -Color $accentColor ) -Type 'DWord' -Force;
	$params = @{
		LiteralPath = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent';
		Name = 'AccentPalette';
	};
	$palette = Get-ItemPropertyValue @params;
	$index = 20;
	$palette[ $index++ ] = $accentColor.R;
	$palette[ $index++ ] = $accentColor.G;
	$palette[ $index++ ] = $accentColor.B;
	$palette[ $index++ ] = $accentColor.A;
	Set-ItemProperty @params -Value $palette -Type 'Binary' -Force;
};

Add-Type -TypeDefinition '
	using System.Drawing;
	using System.Runtime.InteropServices;

	public static class WallpaperSetter {
		[DllImport("user32.dll")]
		private static extern bool SetSysColors(
			int cElements, 
			int[] lpaElements,
			int[] lpaRgbValues
		);

		[DllImport("user32.dll")]
		private static extern bool SystemParametersInfo(
			uint uiAction,
			uint uiParam,
			string pvParam,
			uint fWinIni
		);

		public static void SetDesktopBackground(Color color) {
			SystemParametersInfo(20, 0, "", 0);
			SetSysColors(1, new int[] { 1 }, new int[] { ColorTranslator.ToWin32(color) });
		}

		public static void SetDesktopImage(string file) {
			SystemParametersInfo(20, 0, file, 0);
		}
	}
' -ReferencedAssemblies 'System.Drawing';

function Set-WallpaperColor {
	param(
		[string]
		$HtmlColor
	);

	$color = [System.Drawing.ColorTranslator]::FromHtml( $HtmlColor );
	[WallpaperSetter]::SetDesktopBackground( $color );
	Set-ItemProperty -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers' -Name 'BackgroundType' -Type 'DWord' -Value 1 -Force;
	Set-ItemProperty -Path 'Registry::HKCU\Control Panel\Desktop' -Name 'WallPaper' -Type 'String' -Value '' -Force;
	Set-ItemProperty -Path 'Registry::HKCU\Control Panel\Colors' -Name 'Background' -Type 'String' -Value "$($color.R) $($color.G) $($color.B)" -Force;
}

function Set-WallpaperImage {
	param(
		[string]
		$LiteralPath
	);

	if( $LiteralPath | Test-Path ) {
		[WallpaperSetter]::SetDesktopImage( $LiteralPath );
		Set-ItemProperty -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers' -Name 'BackgroundType' -Type 'DWord' -Value 0 -Force;
		Set-ItemProperty -Path 'Registry::HKCU\Control Panel\Desktop' -Name 'WallPaper' -Type 'String' -Value $LiteralPath -Force;
	} else {
		"Cannot use '$LiteralPath' as a desktop wallpaper because that file does not exist.";
	}
}
Set-WallpaperImage -LiteralPath 'C:\Windows\Setup\Scripts\Wallpaper';

# install Microsoft Visual C++ 
$uri = [uri]::new( 'https://aka.ms/vs/17/release/vc_redist.x64.exe' );
$file = "$env:TEMP\{0}" -f $uri.Segments[-1];
[System.Net.WebClient]::new().DownloadFile( $uri, $file );
Start-Process -FilePath $file -ArgumentList '/quiet /norestart' -Wait;
Remove-Item -LiteralPath $file -ErrorAction 'SilentlyContinue';

###############################################
# 1. Tirar o aviso do Xbox Game Bar
###############################################
if (-Not (Test-Path "HKCU:\Software\Microsoft\GameBar")) {
    New-Item -Path "HKCU:\Software\Microsoft\GameBar" -Force | Out-Null
}
Set-ItemProperty -Path "HKCU:\Software\Microsoft\GameBar" -Name "ShowStartupPanel" -Value 0

###############################################
# 2. Compressão de memória e hibernação
###############################################
Disable-MMAgent -mc
powercfg.exe /hibernate off

###############################################
# 3. Serviços
###############################################
foreach ($s in "SysMain", "DiagTrack", "dmwappushservice") {
    Stop-Service $s -Force -ErrorAction SilentlyContinue
    Set-Service $s -StartupType Disabled -ErrorAction SilentlyContinue
}
Stop-Service "WSearch" -Force -ErrorAction SilentlyContinue
Set-Service "WSearch" -StartupType Manual -ErrorAction SilentlyContinue

###############################################
# 4. Edge não abre sozinho ao ligar
###############################################
$RunKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run"
if (Test-Path $RunKey) {
    (Get-Item $RunKey).Property | Where-Object { $_ -like "MicrosoftEdgeAutoLaunch*" } | ForEach-Object {
        Remove-ItemProperty -Path $RunKey -Name $_ -ErrorAction SilentlyContinue
    }
}

###############################################
# 5. DNS Cloudflare + Google em todas as placas físicas
###############################################
Get-NetAdapter -Physical -ErrorAction SilentlyContinue | ForEach-Object {
    Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses ("1.1.1.1", "8.8.8.8") -ErrorAction SilentlyContinue
}
Clear-DnsClientCache

###############################################
# 6. Windows Terminal (última versão estável)
###############################################
try {
    $ProgressPreference = 'SilentlyContinue'
    $latest = (Invoke-WebRequest -Uri "https://api.github.com/repos/microsoft/terminal/releases" -UseBasicParsing -Headers @{ Accept = 'application/vnd.github.v3+json' }).Content |
        ConvertFrom-Json | Where-Object { -not $_.draft -and -not $_.prerelease } | Select-Object -First 1
    $latest.assets.browser_download_url | Where-Object { $_ -match '\.msixbundle$' } | Select-Object -First 1 | ForEach-Object {
        $uri = [uri]::new($_)
        $file = "$env:TEMP\{0}" -f $uri.Segments[-1]
        [System.Net.WebClient]::new().DownloadFile($uri, $file)
        Add-AppxProvisionedPackage -Online -PackagePath $file -SkipLicense
        Remove-Item -LiteralPath $file -ErrorAction SilentlyContinue
    }
} catch { "Windows Terminal: $_" | Write-Warning }

###############################################
# 7. .NET Framework 3.5 (procura a pasta sources\sxs do pendrive)
#    Sem "return": o script continua depois
###############################################
$sxs = $null
foreach ($drive in [System.IO.DriveInfo]::GetDrives()) {
    $p = Join-Path -Path $drive.RootDirectory -ChildPath 'sources\sxs' -Resolve -ErrorAction SilentlyContinue
    if ($p) { $sxs = $p; break }
}
if ($sxs) {
    Enable-WindowsOptionalFeature -Online -FeatureName 'NetFx3' -Source $sxs -NoRestart
} else {
    'Nao achei sources\sxs. .NET 3.5 nao foi ativado.' | Write-Warning
}

###############################################
# 8. WinRAR pelo winget
#    No primeiro login o winget pode ainda não existir: registra e espera.
#    Se falhar (sem internet), tenta de novo no próximo login.
###############################################
$winget = "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe"
Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe -ErrorAction SilentlyContinue
for ($i = 0; ($i -lt 30) -and -not (Test-Path $winget); $i++) { Start-Sleep 10 }
$ok = $false
if (Test-Path $winget) {
    & $winget install --id RARLab.WinRar --exact --silent --accept-package-agreements --accept-source-agreements
    $ok = ($LASTEXITCODE -eq 0)
}
if (-not $ok) {
    $RunOnce = "HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce"
    if (!(Test-Path $RunOnce)) { New-Item -Path $RunOnce -Force | Out-Null }
    Set-ItemProperty -Path $RunOnce -Name "InstalarWinRAR" -Value 'powershell.exe -WindowStyle Hidden -NoProfile -Command "winget install --id RARLab.WinRar --exact --silent --accept-package-agreements --accept-source-agreements"'
    'WinRAR fica para o proximo login.' | Write-Warning
}

# Lista branca do repo + o que o Windows e os apps precisam para funcionar
[regex]$WhitelistedApps = 'Microsoft.WindowsStore|Microsoft.Windows.Photos|Microsoft.WindowsCalculator|Microsoft.ScreenSketch|Microsoft.DesktopAppInstaller|Microsoft.WindowsCamera|NVIDIACorp.NVIDIAControlPanel|Microsoft.Paint|Microsoft.MicrosoftEdge.Stable|Microsoft.WindowsNotepad|Microsoft.XboxIdentityProvider|MicrosoftCorporationII.QuickAssist|WinRAR.ShellExtension|Microsoft.WindowsTerminal|Microsoft.SecHealthUI|Microsoft.LanguageExperiencePack|Microsoft.VCLibs|Microsoft.UI.Xaml|Microsoft.NET.Native|Microsoft.WindowsAppRuntime'

# Apps instalados
Get-AppxPackage -AllUsers | Where-Object { $_.Name -NotMatch $WhitelistedApps -and $_.NonRemovable -ne $true -and -not $_.IsFramework } | ForEach-Object {
    Remove-AppxPackage -Package $_.PackageFullName -AllUsers -ErrorAction SilentlyContinue
}

# Apps que viriam para novos usuários
Get-AppxProvisionedPackage -Online | Where-Object { $_.PackageName -NotMatch $WhitelistedApps } | ForEach-Object {
    Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName -ErrorAction SilentlyContinue
}

# OneDrive: o Specialize já apagou o instalador e o .reg já bloqueou.
# Aqui só desinstala o que sobrou e limpa.
Stop-Process -Name "OneDrive*" -Force -ErrorAction SilentlyContinue
foreach ($exe in "$env:SYSTEMROOT\SysWOW64\OneDriveSetup.exe", "$env:SYSTEMROOT\System32\OneDriveSetup.exe") {
    if (Test-Path $exe) { Start-Process $exe "/uninstall" -NoNewWindow -Wait }
}

# Se tiver arquivos, guarda na Área de Trabalho
If (Test-Path "$env:USERPROFILE\OneDrive\*") {
    $Backup = "$env:USERPROFILE\Desktop\OneDriveBackupFiles"
    if (!(Test-Path $Backup)) { New-Item -Path $Backup -ItemType Directory -Force | Out-Null }
    Move-Item -Path "$env:USERPROFILE\OneDrive\*" -Destination $Backup -Force
}

foreach ($pasta in "$env:USERPROFILE\OneDrive", "$env:LOCALAPPDATA\Microsoft\OneDrive", "$env:PROGRAMDATA\Microsoft OneDrive", "$env:SYSTEMDRIVE\OneDriveTemp") {
    if (Test-Path $pasta) { Remove-Item $pasta -Force -Recurse -ErrorAction SilentlyContinue }
}

# Tira o OneDrive da lateral do Explorer
foreach ($k in "Registry::HKEY_CLASSES_ROOT\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}", "Registry::HKEY_CLASSES_ROOT\Wow6432Node\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}") {
